  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for gui/public/api-client.js — run log, server-info, orchestrator,
  5	 * and knowledge methods.
  6	 *
  7	 * Uses jsdom + vm.runInThisContext to load the browser-side script, then mocks
  8	 * globalThis.fetch to assert the URLs and options that API methods produce.
  9	 */
 10	
 11	import { describe, it, expect, beforeAll, vi } from 'vitest';
 12	import { readFileSync } from 'node:fs';
 13	import { join } from 'node:path';
 14	import vm from 'node:vm';
 15	
 16	// ---------------------------------------------------------------------------
 17	// Load client script
 18	// ---------------------------------------------------------------------------
 19	
 20	const publicDir = join(__dirname, '../../gui/public');
 21	const apiClientJs = readFileSync(join(publicDir, 'api-client.js'), 'utf-8');
 22	
 23	// Execute once so the API var is available globally (as in a browser)
 24	beforeAll(() => {
 25	  vm.runInThisContext(apiClientJs);
 26	});
 27	
 28	// Declare globalThis.API for TypeScript
 29	declare global {
 30	  // eslint-disable-next-line no-var
 31	  var API: {
 32	    getRunLogs: (repo: string, slug: string) => Promise<unknown>;
 33	    getRunLogEntries: (repo: string, slug: string, filename: string, afterLine?: number) => Promise<unknown>;
 34	    [key: string]: (...args: unknown[]) => Promise<unknown>;
 35	  };
 36	}
 37	
 38	// ---------------------------------------------------------------------------
 39	// Helpers
 40	// ---------------------------------------------------------------------------
 41	
 42	/**
 43	 * Installs a mock `fetch` on globalThis that resolves with the provided JSON
 44	 * body and records the most-recent call arguments.
 45	 */
 46	function mockFetch(responseBody: unknown = null, status = 200) {
 47	  const calls: { url: string; opts: RequestInit }[] = [];
 48	  const mockFn = vi.fn(async (url: string, opts: RequestInit) => {
 49	    calls.push({ url, opts });
 50	    return {
 51	      ok: status >= 200 && status < 300,
 52	      status,
 53	      json: async () => responseBody,
 54	    };
 55	  });
 56	  // jsdom exposes globalThis.fetch — replace it for the duration of the test
 57	  (globalThis as unknown as Record<string, unknown>)['fetch'] = mockFn;
 58	  return calls;
 59	}
 60	
 61	// ---------------------------------------------------------------------------
 62	// getRunLogs
 63	// ---------------------------------------------------------------------------
 64	
 65	describe('API.getRunLogs', () => {
 66	  it('calls GET /api/projects/{repo}/{slug}/runs', async () => {
 67	    const calls = mockFetch([]);
 68	
 69	    await globalThis.API.getRunLogs('my-repo', 'my-slug');
 70	
 71	    expect(calls).toHaveLength(1);
 72	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs');
 73	    expect(calls[0]!.opts.method).toBe('GET');
 74	  });
 75	
 76	  it('encodes both repo and slug via encodeURIComponent', async () => {
 77	    const calls = mockFetch([]);
 78	
 79	    await globalThis.API.getRunLogs('my repo', 'slug with spaces');
 80	
 81	    expect(calls[0]!.url).toBe('/api/projects/my%20repo/slug%20with%20spaces/runs');
 82	  });
 83	});
 84	
 85	// ---------------------------------------------------------------------------
