 89	describe('API.getRunLogEntries', () => {
 90	  it('calls GET /api/projects/{repo}/{slug}/runs/{filename} without ?after when afterLine is omitted', async () => {
 91	    const calls = mockFetch({ entries: [], totalLines: 0 });
 92	
 93	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', 'file.jsonl');
 94	
 95	    expect(calls).toHaveLength(1);
 96	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/file.jsonl');
 97	    expect(calls[0]!.url).not.toContain('?after=');
 98	  });
 99	
100	  it('appends ?after={afterLine} when afterLine is provided', async () => {

101	    const calls = mockFetch({ entries: [], totalLines: 10 });
102	
103	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', '20260225T113355-my-slug.jsonl', 5);
104	
105	    expect(calls).toHaveLength(1);
106	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/20260225T113355-my-slug.jsonl?after=5');
107	  });
108	
109	  it('encodes the filename via encodeURIComponent', async () => {
110	    const calls = mockFetch({ entries: [], totalLines: 0 });
111	
112	    // A filename with a space — unlikely in practice but must be safe
113	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', 'file name.jsonl');
114	
115	    expect(calls[0]!.url).toBe('/api/projects/my-repo/my-slug/runs/file%20name.jsonl');
116	  });
117	
118	  it('encodes both repo and slug via encodeURIComponent', async () => {
119	    const calls = mockFetch({ entries: [], totalLines: 0 });
120	
121	    await globalThis.API.getRunLogEntries('repo/with/slashes', 'slug/with/slashes', 'file.jsonl');
122	
123	    expect(calls[0]!.url).toBe('/api/projects/repo%2Fwith%2Fslashes/slug%2Fwith%2Fslashes/runs/file.jsonl');
124	  });
125	
126	  it('appends ?after=0 when afterLine is explicitly 0 (valid offset)', async () => {
127	    // afterLine: 0 is a legitimate value meaning "skip 0 lines" — include it in the URL
128	    const calls = mockFetch({ entries: [], totalLines: 5 });
129	
130	    await globalThis.API.getRunLogEntries('my-repo', 'my-slug', 'file.jsonl', 0);
131	
132	    expect(calls[0]!.url).toContain('?after=0');
133	  });
134	});
